#include <array>
#include <cstddef>
#include <iostream>
#include <string>

bool HasAllUniqueUppercase(const std::string& input) {
    // 이 실습은 ASCII 실행 문자 집합을 전제로 합니다.
    static_assert('A' == 65 && 'Z' == 90, "ASCII required");
    if (input.size() > 100000) return false;
    std::array<bool, 26> seen = {}; // 모든 칸을 false로 초기화합니다.
    for (unsigned char c : input) {
        // 인덱스로 바꾸기 전에 검사해 범위 밖 접근을 막습니다.
        if (c < 'A' || c > 'Z') return false;
        const std::size_t index = static_cast<std::size_t>(c - 'A');
        if (seen[index]) return false; // 이미 사용한 식별 문자입니다.
        seen[index] = true;
    }
    return true; // 빈 문자열도 중복이 없으므로 true입니다.
}

int main() {
    const std::array<std::string, 6> inputs = {{"ORBIT", "LEVEL", "", "ABCA", "AZ", "aA"}};
    for (const std::string& s : inputs) {
        std::cout << '"' << s << "\" -> " << std::boolalpha
                  << HasAllUniqueUppercase(s) << '\n';
    }
    return 0;
}

#include <array>
#include <cstddef>
#include <iostream>
#include <string>

enum class Status { Invalid, Unique, Duplicate };
struct DuplicateResult {
    Status status;
    std::size_t first;
    std::size_t second;
};

// 대소문자만 합칩니다. 로케일·유니코드 정규화 함수가 아닙니다.
int LetterIndex(unsigned char c) {
    static_assert('A' == 65 && 'Z' == 90 && 'a' == 97 && 'z' == 122,
                  "ASCII required");
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a';
    return -1;
}

DuplicateResult FindFirstDuplicate(const std::string& input) {
    const std::size_t none = std::string::npos;
    if (input.size() > 100000) return {Status::Invalid, none, none};
    // 뒤쪽에 잘못된 바이트가 있어도 중복보다 Invalid를 우선합니다.
    for (unsigned char c : input) {
        if (LetterIndex(c) < 0) return {Status::Invalid, none, none};
    }
    std::array<std::size_t, 26> first;
    first.fill(none); // 0은 유효한 위치이므로 미등장 표식으로 쓸 수 없습니다.
    for (std::size_t i = 0; i < input.size(); ++i) {
        const unsigned char c = static_cast<unsigned char>(input[i]);
        const std::size_t k = static_cast<std::size_t>(LetterIndex(c));
        if (first[k] != none) {
            return {Status::Duplicate, first[k], i};
        }
        first[k] = i; // 첫 등장만 저장합니다. 입력 문자열은 수정하지 않습니다.
    }
    return {Status::Unique, none, none};
}

int main() {
    const std::array<std::string, 5> inputs = {{"Orbit", "aBca", "ABbA", "", "AA!"}};
    for (const std::string& s : inputs) {
        const DuplicateResult result = FindFirstDuplicate(s);
        std::cout << '"' << s << "\" -> ";
        if (result.status == Status::Invalid) std::cout << "Invalid";
        else if (result.status == Status::Unique) std::cout << "Unique";
        else std::cout << "Duplicate (" << result.first << ", " << result.second << ')';
        std::cout << '\n';
    }
    return 0;
}
